from collections import deque

class Solution:
    def friendRequests(self, n: int, restrictions: List[List[int]], requests: List[List[int]]) -> List[bool]:
        adj = [[] for _ in range(n)]
        res = []

        def components():
            comp = [-1] * n
            cid = 0
            for s in range(n):
                if comp[s] != -1:
                    continue
                dq = deque([s])
                comp[s] = cid
                while dq:
                    u = dq.popleft()
                    for w in adj[u]:
                        if comp[w] == -1:
                            comp[w] = cid
                            dq.append(w)
                cid += 1
            return comp

        for u, v in requests:
            comp = components()
            ok = True
            for x, y in restrictions:
                if ((comp[x] == comp[u] and comp[y] == comp[v]) or
                        (comp[y] == comp[u] and comp[x] == comp[v])):
                    ok = False
                    break
            res.append(ok)
            if ok:
                adj[u].append(v)
                adj[v].append(u)
        return res

