class Solution {
public:
    vector<bool> friendRequests(int n, vector<vector<int>>& restrictions, vector<vector<int>>& requests) {
        vector<vector<int>> adj(n);
        vector<bool> res;

        auto components = [&]() {
            vector<int> comp(n, -1);
            int cid = 0;
            for (int s = 0; s < n; s++) {
                if (comp[s] != -1) continue;
                queue<int> q;
                q.push(s);
                comp[s] = cid;
                while (!q.empty()) {
                    int u = q.front();
                    q.pop();
                    for (int w : adj[u])
                        if (comp[w] == -1) { comp[w] = cid; q.push(w); }
                }
                cid++;
            }
            return comp;
        };

        for (auto& req : requests) {
            vector<int> comp = components();
            bool ok = true;
            for (auto& r : restrictions) {
                int x = r[0], y = r[1];
                if ((comp[x] == comp[req[0]] && comp[y] == comp[req[1]]) ||
                    (comp[y] == comp[req[0]] && comp[x] == comp[req[1]])) {
                    ok = false;
                    break;
                }
            }
            res.push_back(ok);
            if (ok) {
                adj[req[0]].push_back(req[1]);
                adj[req[1]].push_back(req[0]);
            }
        }
        return res;
    }
};

