class Solution {
    public boolean[] friendRequests(int n, int[][] restrictions, int[][] requests) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        boolean[] res = new boolean[requests.length];

        for (int j = 0; j < requests.length; j++) {
            int[] comp = components(n, adj);
            int u = requests[j][0], v = requests[j][1];
            boolean ok = true;
            for (int[] r : restrictions) {
                int x = r[0], y = r[1];
                if ((comp[x] == comp[u] && comp[y] == comp[v]) ||
                    (comp[y] == comp[u] && comp[x] == comp[v])) {
                    ok = false;
                    break;
                }
            }
            res[j] = ok;
            if (ok) {
                adj.get(u).add(v);
                adj.get(v).add(u);
            }
        }
        return res;
    }

    private int[] components(int n, List<List<Integer>> adj) {
        int[] comp = new int[n];
        Arrays.fill(comp, -1);
        int cid = 0;
        for (int s = 0; s < n; s++) {
            if (comp[s] != -1) continue;
            Queue<Integer> q = new ArrayDeque<>();
            q.add(s);
            comp[s] = cid;
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int w : adj.get(u))
                    if (comp[w] == -1) { comp[w] = cid; q.add(w); }
            }
            cid++;
        }
        return comp;
    }
}

